using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class BRApply {
 const string E="Assets/Afrer_Seconds/05.Model/Environment/B2/",P="Assets/Afrer_Seconds/05.Model/Props/B2/";static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static string H=>R+"/SourceAssets/B2_SurfaceRefinement/";static string O=>R+"/Docs/Review/2026-11-10_B2_SurfaceRefinement/";
 static Scene Check(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||s.isDirty||!s.path.EndsWith("Level_B2_Circular.unity"))throw new Exception("Saved B2 required");return s;}
 static Material Mat(string n){string path=E+"Materials/"+n+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(!m){m=new Material(Shader.Find("Universal Render Pipeline/Lit")){name=n};AssetDatabase.CreateAsset(m,path);}return m;}
 static Material Pbr(string stem){var m=Mat(stem);m.SetColor("_BaseColor",Color.white);m.SetTexture("_BaseMap",AssetDatabase.LoadAssetAtPath<Texture2D>(E+"Textures/"+stem+"_Base.png"));m.SetTexture("_BumpMap",AssetDatabase.LoadAssetAtPath<Texture2D>(E+"Textures/"+stem+"_Normal.png"));m.SetTexture("_MetallicGlossMap",AssetDatabase.LoadAssetAtPath<Texture2D>(E+"Textures/"+stem+"_MS.png"));m.SetFloat("_Metallic",1);m.SetFloat("_Smoothness",1);m.SetFloat("_BumpScale",.65f);m.EnableKeyword("_NORMALMAP");m.EnableKeyword("_METALLICSPECGLOSSMAP");EditorUtility.SetDirty(m);return m;}
 static Material Solid(string key,Color c,float metallic=.0f,float smooth=.4f){var m=Mat("BR_"+key);m.SetColor("_BaseColor",c);m.SetFloat("_Metallic",metallic);m.SetFloat("_Smoothness",smooth);EditorUtility.SetDirty(m);return m;}
 public static object Import(){Check();AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);int textures=0;foreach(var path in Directory.GetFiles(E+"Textures","BR_*.png").Concat(Directory.GetFiles(P+"Textures","BR_*.png"))){var ti=(TextureImporter)AssetImporter.GetAtPath(path);ti.textureType=path.EndsWith("_Normal.png")?TextureImporterType.NormalMap:TextureImporterType.Default;ti.sRGBTexture=!path.EndsWith("_MS.png")&&!path.EndsWith("_Normal.png");ti.mipmapEnabled=true;ti.anisoLevel=8;ti.maxTextureSize=2048;ti.textureCompression=TextureImporterCompression.CompressedHQ;ti.wrapMode=path.Contains("Floor_")||path.Contains("Display_")?TextureWrapMode.Clamp:TextureWrapMode.Mirror;ti.SaveAndReimport();textures++;}
 var mats=new Dictionary<string,Material>();foreach(string key in new[]{"Steel","Coat","Grip","Concrete"})mats["BR_"+key]=Pbr("BR_"+key);
 mats["BR_Dark"]=Solid("Dark",new Color(.035f,.043f,.043f),.38f,.31f);mats["BR_Rubber"]=Solid("Rubber",new Color(.023f,.026f,.024f),0,.18f);mats["BR_Indicator"]=Solid("Indicator",new Color(.14f,.38f,.24f),.1f,.4f);mats["BR_Red"]=Solid("Red",new Color(.33f,.045f,.025f),.1f,.36f);mats["BR_Hazard"]=Solid("Hazard",new Color(.43f,.30f,.08f),.2f,.29f);mats["BR_Paper"]=Solid("Paper",new Color(.65f,.65f,.56f),0,.18f);
 for(int i=1;i<=7;i++){var m=Mat("BR_Display_"+i.ToString("00"));var tex=AssetDatabase.LoadAssetAtPath<Texture2D>(P+"Textures/BR_Display_"+i.ToString("00")+".png");m.SetColor("_BaseColor",Color.white);m.SetTexture("_BaseMap",tex);m.SetFloat("_Smoothness",i<=2?.28f:.18f);if(i<=2){m.EnableKeyword("_EMISSION");m.SetTexture("_EmissionMap",tex);m.SetColor("_EmissionColor",Color.white*.8f);}EditorUtility.SetDirty(m);mats[m.name]=m;}
 foreach(var floor in JArray.Parse(File.ReadAllText(H+"floors.json")))Pbr((string)floor["stem"]);
 int models=0;foreach(var file in Directory.GetFiles(P,"BR_*.fbx")){var mi=(ModelImporter)AssetImporter.GetAtPath(file);mi.importAnimation=false;mi.importCameras=false;mi.importLights=false;mi.isReadable=true;mi.importNormals=ModelImporterNormals.Import;mi.importTangents=ModelImporterTangents.CalculateMikk;foreach(var kv in mats)mi.AddRemap(new AssetImporter.SourceAssetIdentifier(typeof(Material),kv.Key),kv.Value);mi.SaveAndReimport();models++;}AssetDatabase.SaveAssets();return new{textures,models,materials=mats.Count};}
 static Mesh MeshCopy(MeshFilter mf,string key){string dir=E+"BR_Meshes";if(!AssetDatabase.IsValidFolder(dir))AssetDatabase.CreateFolder(E.TrimEnd('/'),"BR_Meshes");string path=dir+"/"+key+".asset";var m=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(m)return m;m=UnityEngine.Object.Instantiate(mf.sharedMesh);m.name=key;AssetDatabase.CreateAsset(m,path);return m;}
 static GameObject Put(string name,Transform parent,string objectName){var g=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(P+name+".fbx"),parent);g.name=objectName;g.transform.localPosition=Vector3.zero;g.transform.localRotation=Quaternion.identity;var hi=g.GetComponentsInChildren<Renderer>();var low=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(P+name+"_Far.fbx"),g.transform);low.name="Distance_LOD1";low.transform.localPosition=Vector3.zero;low.transform.localRotation=Quaternion.identity;var lod=g.AddComponent<LODGroup>();lod.fadeMode=LODFadeMode.CrossFade;lod.SetLODs(new[]{new LOD(.12f,hi),new LOD(0,low.GetComponentsInChildren<Renderer>())});lod.RecalculateBounds();return g;}
 static void Save(Scene s){foreach(var t in s.GetRootGameObjects().Where(g=>g.name.StartsWith("B2_")).SelectMany(g=>g.GetComponentsInChildren<Transform>(true)))if(PrefabUtility.IsPartOfPrefabInstance(t)){PrefabUtility.RecordPrefabInstancePropertyModifications(t);PrefabUtility.RecordPrefabInstancePropertyModifications(t.gameObject);foreach(var c in t.GetComponents<Component>())if(c)PrefabUtility.RecordPrefabInstancePropertyModifications(c);}Physics.SyncTransforms();AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);}
 public static object Run(){var s=Check();if(GameObject.Find("B2_C01_LubricationStation"))throw new Exception("Already applied; use scoped repair");var plan=JObject.Parse(File.ReadAllText(H+"plan.json"));var all=s.GetRootGameObjects().Where(g=>g.name.StartsWith("B2_")).SelectMany(g=>g.GetComponentsInChildren<Transform>()).ToArray();int floors=0,tunnels=0,deckRenderers=0,consoles=0;var changes=new List<object>();
 foreach(var row in JArray.Parse(File.ReadAllText(H+"floors.json"))){var g=GameObject.Find((string)row["name"]);var mf=g.GetComponent<MeshFilter>();var m=MeshCopy(mf,g.name+"_WornSurface");var vs=m.vertices;var uv=new Vector2[vs.Length];var b=g.GetComponent<Renderer>().bounds;for(int i=0;i<vs.Length;i++){var wp=g.transform.TransformPoint(vs[i]);uv[i]=new Vector2((wp.x-b.min.x)/b.size.x,(wp.z-b.min.z)/b.size.z);}m.uv=uv;m.RecalculateTangents();EditorUtility.SetDirty(m);mf.sharedMesh=m;g.GetComponent<Renderer>().sharedMaterial=AssetDatabase.LoadAssetAtPath<Material>(E+"Materials/"+(string)row["stem"]+".mat");floors++;}
 var steel=AssetDatabase.LoadAssetAtPath<Material>(E+"Materials/BR_Steel.mat");var coat=AssetDatabase.LoadAssetAtPath<Material>(E+"Materials/BR_Coat.mat");var grip=AssetDatabase.LoadAssetAtPath<Material>(E+"Materials/BR_Grip.mat");var concrete=AssetDatabase.LoadAssetAtPath<Material>(E+"Materials/BR_Concrete.mat");
 foreach(var t in all){var mr=t.GetComponent<MeshRenderer>();if(!mr||!mr.enabled)continue;var mf=t.GetComponent<MeshFilter>();if(!mf||!mf.sharedMesh)continue;string path=AssetDatabase.GetAssetPath(mf.sharedMesh);bool deck=path.Contains("OperationsDeck")&&!path.Contains("Collision")||path.Contains("_UpperWalk")||path.Contains("BM_VerticalStairs");if(deck){mr.sharedMaterials=mr.sharedMaterials.Select(m=>m.name=="BCM_Steel"?steel:m.name=="BCM_Hazard"||m.name=="BCM_Mark"?grip:m.name=="BCM_Coat"?coat:m.name=="BCM_Floor"?steel:m).ToArray();deckRenderers++;}
 if(t.name.EndsWith("_TunnelShell")){var mesh=MeshCopy(mf,t.name+"_WornSurface");var mats=mr.sharedMaterials;var uv=mesh.uv;var vs=mesh.vertices;for(int sub=0;sub<mats.Length;sub++)if(mats[sub].name=="BCM_Floor"){foreach(int vi in mesh.GetIndices(sub)){var p=t.TransformPoint(vs[vi]);uv[vi]=new Vector2(p.x/2,p.z/2);}mats[sub]=concrete;}mesh.uv=uv;mesh.RecalculateTangents();EditorUtility.SetDirty(mesh);mf.sharedMesh=mesh;mr.sharedMaterials=mats;tunnels++;}}
 var guide=GameObject.Find("B2_DestinationGuidance");if(guide)guide.SetActive(false);
 var detail=GameObject.Find("B2_FloorDetails");if(detail){var mf=detail.GetComponent<MeshFilter>();var mesh=MeshCopy(mf,"B2_FloorDetails_NoPaint");var mats=detail.GetComponent<MeshRenderer>().sharedMaterials;for(int sub=0;sub<mats.Length;sub++)if(mats[sub].name=="BCM_Hazard")mesh.SetTriangles(new int[0],sub);mf.sharedMesh=mesh;EditorUtility.SetDirty(mesh);}
 foreach(var p in plan["placements"].Where(p=>(string)p["model"]=="BM_ControlConsole")){var g=GameObject.Find((string)p["name"]);if(!g)throw new Exception("Console missing "+p["name"]);foreach(var mr in g.GetComponentsInChildren<Renderer>())mr.enabled=false;foreach(var lod in g.GetComponentsInChildren<LODGroup>())lod.enabled=false;Put("BR_PlantConsole",g.transform,"B2_"+(string)p["room"]+"_MachineryConsole_Visual");consoles++;}
 foreach(string name in new[]{"B2_C02_Ops_PartsStaging_13","B2_C02_Ops_PartsStaging_14"}){var g=GameObject.Find(name);var p=plan["placements"].Single(p=>(string)p["name"]==name);g.transform.localPosition=new Vector3((float)p["position"][0],name.EndsWith("13")?.185f:0,(float)p["position"][2]);g.transform.localRotation=Quaternion.Euler(0,(float)p["yaw"],0);changes.Add(new{name,position=g.transform.position.ToString()});}
 foreach(string name in new[]{"B2_C01_LubricationStation","B2_C02_PartsCradle"}){var p=plan["placements"].Single(p=>(string)p["name"]==name);var g=Put((string)p["model"],GameObject.Find("B2_"+(string)p["room"]+"_Operations").transform,name);g.transform.localPosition=new Vector3((float)p["position"][0],0,(float)p["position"][2]);g.transform.localRotation=Quaternion.Euler(0,(float)p["yaw"],0);var bc=g.AddComponent<BoxCollider>();bc.center=new Vector3((float)p["center"][0],(float)p["center"][1],(float)p["center"][2]);bc.size=new Vector3((float)p["size"][0],(float)p["size"][1],(float)p["size"][2]);}
 foreach(var c in s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Camera>(true)))c.useOcclusionCulling=false;Save(s);Directory.CreateDirectory(O);var report=new{floors,tunnels,deckRenderers,consoles,moved=changes,guidanceDisabled=guide&&!guide.activeSelf,saved=!s.isDirty};File.WriteAllText(O+"applied.json",JsonConvert.SerializeObject(report,Formatting.Indented));return report;}
}
